function plannerContentRows(){try{return typeof window.orderContentRows==='function'?(window.orderContentRows()||[]):[]}catch(e){return[]}}
function uniqueValues(list){var seen={};return(list||[]).filter(function(value){value=String(value||'').trim();if(!value||seen[value])return false;seen[value]=1;return true})}
function plannerRowsForProduct(product){return plannerContentRows().filter(function(row){return row&&(!product||!row.brand||row.brand===product)})}
function plannerMatches(d){return plannerRowsForProduct(d.product).filter(function(row){if((row.name||'')!==(d.name||''))return false;return !d.hook||!row.hook||row.hook===d.hook})}
function plannerProducts(current){var values=uniqueValues(PLANNER_PRODUCTS.concat(plannerContentRows().map(function(row){return row&&row.brand})));if(current&&values.indexOf(current)<0)values.unshift(current);return option('','-- เลือกสินค้า --',current)+values.map(function(value){return option(value,value,current)}).join('')}
function plannerJobs(d){var values=d.product?uniqueValues(plannerRowsForProduct(d.product).map(function(row){return row&&row.name})):[],current=d.contentChoice||'';if(current&&values.indexOf(current)<0)values.unshift(current);var label=!plannerContentRows().length?'-- กำลังโหลด Content Tracker --':!d.product?'-- เลือกสินค้าก่อน --':!values.length?'-- ไม่พบงานของสินค้านี้ --':'-- เลือกงานจาก Content Tracker --';return option('',label,current)+values.map(function(name){return option(name,name,current)}).join('')}
function plannerHookRows(d){return plannerRowsForProduct(d.product).filter(function(row){return row&&(row.name||'')===(d.name||'')})}
function plannerHooks(d,current,placeholder){var values=uniqueValues([current].concat(plannerHookRows(d).map(function(row){return row&&row.hook})));return option('',placeholder,current)+values.map(function(value){return option(value,value,current)}).join('')}
function plannerContentStatus(d){var count=plannerRowsForProduct(d.product).length;if(!plannerContentRows().length)return'<div class="rbp-content-status is-loading">กำลังโหลดรายการจาก Content Tracker…</div>';if(!d.product)return'<div class="rbp-content-status">เลือกสินค้า แล้วระบบจะแสดงเฉพาะงาน Hook และลิงก์ของสินค้านั้น</div>';if(!count)return'<div class="rbp-content-status is-empty">ไม่พบงานของ '+esc(d.product)+' ใน Content Tracker — ยังพิมพ์ชื่องานเองได้</div>';return'<div class="rbp-content-status is-ready">พบ '+count+' รายการของ '+esc(d.product)+' · เลือกงานและ Hook เพื่อดึงลิงก์ให้ตรงเวอร์ชัน</div>'}
function plannerProductAssets(){return window._rbProductAssetLinks||{}}
function plannerKnownAsset(value,kind){var found=false;Object.keys(plannerProductAssets()).forEach(function(product){if((plannerProductAssets()[product][kind]||[]).indexOf(value)>=0)found=true});return found}
function applyPlannerProductAssets(d,force){var assets=plannerProductAssets()[d.product]||{},changed=false;[['footage','footageLink'],['review','reviewLink']].forEach(function(pair){var urls=assets[pair[0]]||[],current=d[pair[1]]||'';if(force||!current||plannerKnownAsset(current,pair[0])){var next=urls[0]||'';if(next!==current){d[pair[1]]=next;changed=true}}});return changed}
