function plannerLeaveGuard(d){if(!d.assignee||!d.deadline)return'<div class="rbp-parity-guard is-neutral"><b>ตรวจวันหยุดอัตโนมัติ</b><span>เลือกผู้รับผิดชอบและ Deadline เพื่อเช็กตารางวันหยุด</span></div>';var away=leaveCodes(d.deadline);return away[d.assignee]?'<div class="rbp-parity-guard is-bad"><b>พบวันหยุดของ '+esc(d.assignee)+'</b><span>ระบบจะใช้กฎจัดคนว่างอัตโนมัติ หรือพักคิวให้ Supervisor ตรวจ</span></div>':'<div class="rbp-parity-guard is-ok"><b>✓ ผู้รับผิดชอบใช้งานได้</b><span>'+esc(d.assignee)+' ไม่มีวันหยุดตรงกับ Deadline นี้</span></div>'}
function plannerGallery(d){if(!d.briefImages.length)return'<span class="rbp-gallery-empty">ยังไม่ได้แนบรูปตัวอย่าง</span>';return d.briefImages.map(function(image,index){return'<figure class="rbp-brief-thumb"><img src="'+esc(image.data||'')+'" alt="'+esc(image.name||'รูปตัวอย่าง')+'"><figcaption>'+esc(image.name||'รูป '+(index+1))+'</figcaption><button type="button" data-action="remove-brief-image" data-index="'+index+'" aria-label="ลบรูป">×</button></figure>'}).join('')}
