function plannerOrderMatches(order,draft){if(!order||!draft)return false;return order.sourceDraftId===draft.id||!!(draft.orderId&&(order.id===draft.orderId||order.orderId===draft.orderId))}
function plannerOrderForDraft(draft){return allOrders().find(function(order){return plannerOrderMatches(order,draft)})||null}
function dispatchedRows(){return rows.filter(function(d){return d.status==='dispatched'}).sort(function(a,b){return Number(b.dispatchedAt||0)-Number(a.dispatchedAt||0)})}
function historyTime(value){if(!value)return'ไม่พบเวลาที่สั่ง';try{return new Date(value).toLocaleString('th-TH',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'})}catch(e){return String(value)}}
function historyStatus(value){var found=WORK_STATUSES.find(function(pair){return pair[0]===value});return found?found[1]:(value||'มอบหมาย')}
function historyValue(label,value,wide){return'<div class="rbp-history-value '+(wide?'is-wide':'')+'"><span>'+esc(label)+'</span><b>'+esc(value||'—')+'</b></div>'}
