function boot(){installButton();document.addEventListener('click',handlePlannerExtras);document.addEventListener('change',handlePlannerFileChange);document.addEventListener('input',handlePlannerParityChange);document.addEventListener('change',handlePlannerParityChange);setInterval(installButton,1800);setInterval(function(){if(window._rbUser)runWorker()},60000);setTimeout(function(){if(window._rbUser)runWorker()},5000);window.addEventListener('online',function(){if(window._rbUser)runWorker();refreshPlannerFromCloud()});window.addEventListener('pagehide',function(){if(isSupervisor()&&rows.length)saveDraftsImmediately()});window.addEventListener('storage',function(e){if(e.key==='rb_session')setTimeout(installButton,0);if(e.key===DRAFT_KEY||e.key===DELETE_KEY)scheduleExternalSync(false)});window.addEventListener('focus',function(){refreshPlannerFromCloud()});document.addEventListener('visibilitychange',function(){if(!document.hidden)refreshPlannerFromCloud()})}
